pub trait Movable { fn pos(&self) -> Position; fn set_pos(&mut self, p: Position); }

pub fn move_to<T: Movable>(t: &mut T, to: Position) { t.set_pos(to); }
pub fn move_by<T: Movable>(t: &mut T, dx: i32, dy: i32) {
    let p = t.pos();
    t.set_pos(Position { x: p.x + dx, y: p.y + dy });
}

move_to(&mut shape, Position { x: 3, y: 4 });   // no trait import, no member lookup
